class MockOrderService:

    def __init__(self):
        self.orders = {}

    def create(self, operation_id):

        if operation_id not in self.orders:

            self.orders[operation_id] = {
                "order_id": "ORDER-101",
                "status": "confirmed"
            }

            # Simulate lost response after commit.
            raise TimeoutError(
                "Response lost after write"
            )

        return self.orders[operation_id]

    def get_status(self, operation_id):
        return self.orders.get(operation_id)

def test_reconcile_after_timeout():

    service = MockOrderService()

    operation_id = "OP-101"

    try:
        service.create(operation_id)

    except TimeoutError:

        result = service.get_status(
            operation_id
        )

        assert result is not None

        assert result["status"] == "confirmed"

    assert len(service.orders) == 1
```

This test demonstrates the desired behavior in an in-memory simulation. It does not prove that an actual external API implements equivalent idempotency or reconciliation guarantees.
